cases.text:
world "Skyhold"
tile mt_core "Matter core" as game_asset ui_panel website
  mesh primitive {"rot": [0.6,0,0.6], "shape": "box", "size": [0.9,0.9,0.9]}
  material primitive {"color": [0.5,0.36,1], "emissive": 0.25, "pattern": "checker", "scale": 0.3}
  behavior scripted {"ops": [{"amp": 0.18, "op": "bob", "rate": 1.4},{"axis": "y", "op": "spin", "rate": 0.5},{"amp": 0.35, "op": "pulse", "rate": 2}]}
  logic rule {"rules": [{"do": [{"set": ["stored",["+",["var", "stored"],["floor",["var", "energy"]]]]},{"set": ["energy",0]}], "on": "surge"}], "vars": {"energy": {"accrue": {"cap": 21600, "rate": 1}, "base": 0}, "stored": 0}}
  socket mount attach at 0 0 0
  socket surge signal in "Harvest energy"
tile mt_island "Floating island" as world game_asset ui_panel website
  mesh generated {"depth": 4, "generator": "terrain", "height": 1.6, "plateau": 1, "radius": 5.5, "seed": 3}
  material primitive {"color": [0.25,0.58,0.36]}
  socket top attach at 0 1 0
  socket dock attach at 1.25 1 0.75
  control seed {"binds": [{"at": "data.seed", "facet": "mesh", "tile": ""}], "id": "seed", "label": "Terrain seed", "max": 60, "min": 1, "step": 1, "type": "number"}
  control height {"binds": [{"at": "data.height", "facet": "mesh", "tile": ""}], "id": "height", "label": "Hill height", "max": 3, "min": 0.4, "step": 0.1, "type": "number"}
tile mt_rover "Sky rover" as vehicle game_asset ui_panel website
  at 0 0.4 0
  mesh primitive {"parts": [{"pos": [0,0.35,0], "shape": "box", "size": [1.5,0.4,2.6]},{"pos": [0,0.72,0.75], "shape": "wedge", "size": [1.5,0.35,0.9]},{"color": [0.2,0.5,1], "pos": [0,0.75,-0.25], "shape": "box", "size": [1.2,0.4,1.1]}]}
  material primitive {"color": [0.78,0.82,0.92], "emissive": ["*",["var", "moving"],0.25], "glow": [0.3,0.6,1]}
  behavior scripted {"ops": [{"by": ["var", "odometer"], "op": "orbit", "radius": 7.6, "rate": 0.22},{"amp": 0.07, "op": "bob", "rate": 2}]}
  logic rule {"rules": [{"do": [{"set": ["odometer",["var", "odometer"]]},{"set": ["moving",["-",1,["var", "moving"]]]},{"emit": "rolling"}], "on": "drive"}], "vars": {"moving": 0, "odometer": {"accrue": {"rate": ["var", "moving"]}, "base": 0}}}
  socket w_fl attach at -0.95 0.05 0.85
  socket w_fr attach at 0.95 0.05 0.85
  socket w_rl attach at -0.95 0.05 -0.85
  socket w_rr attach at 0.95 0.05 -0.85
  socket drive signal in "Drive / stop"
  socket rolling signal out
  control orbit {"binds": [{"at": "data.ops.0.radius", "facet": "behavior", "tile": ""}], "id": "orbit", "label": "Orbit radius", "max": 14, "min": 6, "step": 0.2, "type": "number"}
tile mt_switch "Dock switch" as game_asset ui_panel
  mesh primitive {"parts": [{"pos": [0,0.25,0], "shape": "cylinder", "size": [0.5,0.5,0.5]},{"color": [1,0.55,0.3], "pos": [0,0.6,0], "shape": "sphere", "size": [0.34,0.34,0.34]}]}
  material primitive {"color": [0.3,0.6,1], "emissive": 0.15}
  logic rule {"rules": [{"do": [{"set": ["presses",["+",["var", "presses"],1]]},{"emit": "pressed"}], "on": "press"}], "vars": {"presses": 0}}
  socket foot attach at 0 0 0
  socket press signal in "Press"
  socket pressed signal out
tile mt_tower "Beacon tower" as game_asset ui_panel website
  mesh generated {"generator": "tower", "levels": 3, "radius": 0.6, "seed": 4}
  material primitive {"color": [0.62,0.66,0.78], "emissive": ["*",["var", "beacon"],0.45], "glow": [0.35,0.65,1]}
  logic rule {"rules": [{"do": [{"set": ["beacon",["-",1,["var", "beacon"]]]},{"emit": "lit"}], "on": "toggle"}], "vars": {"beacon": 0}}
  socket base attach at 0 0 0
  socket roof attach at 0 4.9 0
  socket toggle signal in "Toggle beacon"
  socket lit signal out
  control levels {"binds": [{"at": "data.levels", "facet": "mesh", "tile": ""},{"at": "sockets.1.pos.1", "expr": ["+",["*",["var", "value"],1.1],1.6], "facet": "connect", "tile": ""}], "id": "levels", "label": "Levels", "max": 7, "min": 1, "step": 1, "type": "number"}
tile mt_wheel_fl "Wheel FL" as game_asset
  mesh primitive {"rot": [0,0,1.5707963267948966], "segments": 12, "shape": "cylinder", "size": [0.7,0.3,0.7]}
  material primitive {"color": [0.16,0.18,0.3], "pattern": "stripes", "scale": 0.17}
  behavior scripted {"ops": [{"axis": "x", "by": ["var", "turns"], "op": "spin", "rate": 3}]}
  logic rule {"rules": [{"do": [{"set": ["turns",["var", "turns"]]},{"set": ["rolling",["-",1,["var", "rolling"]]]}], "on": "roll"}], "vars": {"rolling": 0, "turns": {"accrue": {"rate": ["var", "rolling"]}, "base": 0}}}
  socket hub attach at 0 0 0
  socket roll signal in
tile mt_wheel_fr "Wheel FR" as game_asset
  mesh primitive {"rot": [0,0,1.5707963267948966], "segments": 12, "shape": "cylinder", "size": [0.7,0.3,0.7]}
  material primitive {"color": [0.16,0.18,0.3], "pattern": "stripes", "scale": 0.17}
  behavior scripted {"ops": [{"axis": "x", "by": ["var", "turns"], "op": "spin", "rate": 3}]}
  logic rule {"rules": [{"do": [{"set": ["turns",["var", "turns"]]},{"set": ["rolling",["-",1,["var", "rolling"]]]}], "on": "roll"}], "vars": {"rolling": 0, "turns": {"accrue": {"rate": ["var", "rolling"]}, "base": 0}}}
  socket hub attach at 0 0 0
  socket roll signal in
tile mt_wheel_rl "Wheel RL" as game_asset
  mesh primitive {"rot": [0,0,1.5707963267948966], "segments": 12, "shape": "cylinder", "size": [0.7,0.3,0.7]}
  material primitive {"color": [0.16,0.18,0.3], "pattern": "stripes", "scale": 0.17}
  behavior scripted {"ops": [{"axis": "x", "by": ["var", "turns"], "op": "spin", "rate": 3}]}
  logic rule {"rules": [{"do": [{"set": ["turns",["var", "turns"]]},{"set": ["rolling",["-",1,["var", "rolling"]]]}], "on": "roll"}], "vars": {"rolling": 0, "turns": {"accrue": {"rate": ["var", "rolling"]}, "base": 0}}}
  socket hub attach at 0 0 0
  socket roll signal in
tile mt_wheel_rr "Wheel RR" as game_asset
  mesh primitive {"rot": [0,0,1.5707963267948966], "segments": 12, "shape": "cylinder", "size": [0.7,0.3,0.7]}
  material primitive {"color": [0.16,0.18,0.3], "pattern": "stripes", "scale": 0.17}
  behavior scripted {"ops": [{"axis": "x", "by": ["var", "turns"], "op": "spin", "rate": 3}]}
  logic rule {"rules": [{"do": [{"set": ["turns",["var", "turns"]]},{"set": ["rolling",["-",1,["var", "rolling"]]]}], "on": "roll"}], "vars": {"rolling": 0, "turns": {"accrue": {"rate": ["var", "rolling"]}, "base": 0}}}
  socket hub attach at 0 0 0
  socket roll signal in
wire a_core attach mt_tower.roof -> mt_core.mount
wire a_switch attach mt_island.dock -> mt_switch.foot
wire a_tower attach mt_island.top -> mt_tower.base
wire a_wheel_fl attach mt_rover.w_fl -> mt_wheel_fl.hub
wire a_wheel_fr attach mt_rover.w_fr -> mt_wheel_fr.hub
wire a_wheel_rl attach mt_rover.w_rl -> mt_wheel_rl.hub
wire a_wheel_rr attach mt_rover.w_rr -> mt_wheel_rr.hub
wire s_lit signal mt_tower.lit -> mt_core.surge
wire s_switch signal mt_switch.pressed -> mt_tower.toggle
wire s_wheel_fl signal mt_rover.rolling -> mt_wheel_fl.roll
wire s_wheel_fr signal mt_rover.rolling -> mt_wheel_fr.roll
wire s_wheel_rl signal mt_rover.rolling -> mt_wheel_rl.roll
wire s_wheel_rr signal mt_rover.rolling -> mt_wheel_rr.roll
